`timescale 1ns / 1ps
//
// tb_illegal.v  illegal-instruction detection test (program: illegal.hex,
//               generated by tools/gen_illegal_hex.py)
//
//   0x00 addi x1,x0,5
//   0x04 mulh x2,x1,x1          ILLEGAL (only MUL of RV32M is implemented)  -> x2 must stay 0 (acts as NOP)
//   0x08 addi x3,x0,7
//   0x0c lb   x4,0(x0)          ILLEGAL (only lw is implemented) -> x4 stays 0
//   0x10 addi x5,x0,9
//   0x14 0x00000000             ILLEGAL (all-zero word)
//   0x18 fence                  ILLEGAL
//   0x1c ecall                  ILLEGAL
//   0x20 sb   x1,0(x0)          ILLEGAL -> must NOT write dmem[0]
//   0x24 slli x6,x1,1 with funct7=0100000   ILLEGAL (used to execute as SLL) -> x6 stays 0
//   0x28 addi x7,x0,1
//   0x2c beq  x0,x0,+8          always taken, skips 0x30
//   0x30 mulh x9,x1,x1          wrong-path illegal: flushed, must NOT be reported
//   0x34 addi x8,x0,3
//   0x38 custom-0 funct7=1      ILLEGAL (only XDOTP16 funct7=0/funct3=0 defined) -> x10 stays 0
//   0x3c custom-0 funct3=1      ILLEGAL -> x11 stays 0
//   0x40 jal  x0,0              spin
//
// Expected: 9 committed illegal instructions, first at pc=0x04, sticky flag set.
//
module tb_illegal;
    reg clk = 0;
    reg rst_n = 0;
    wire        illegal_flag;
    wire [31:0] illegal_pc;

    rv32i_pipeline #(.IMEM_FILE("illegal.hex")) dut (
        .clk            (clk),
        .rst_n          (rst_n),
        .illegal_out    (illegal_flag),
        .illegal_pc_out (illegal_pc)
    );

    always #5 clk = ~clk;

    integer errors = 0;
    integer n_illegal = 0;
    always @(posedge clk)
        if (rst_n && dut.ex_valid && dut.ex_illegal) n_illegal = n_illegal + 1;

    task check_reg;
        input [127:0] name;
        input [4:0]   idx;
        input [31:0]  exp;
        begin
            if (dut.regfile_inst.regs[idx] !== exp) begin
                $display("FAIL %-22s x%0d = 0x%08h, expected 0x%08h", name, idx, dut.regfile_inst.regs[idx], exp);
                errors = errors + 1;
            end else
                $display("PASS %-22s x%0d = 0x%08h", name, idx, exp);
        end
    endtask

    initial begin
        #15 rst_n = 1;
        #1000;

        check_reg("mulh acts as NOP",       2, 0);
        check_reg("lb acts as NOP",        4, 0);
        check_reg("bad slli acts as NOP",  6, 0);
        check_reg("legal addi x1",         1, 5);
        check_reg("legal addi x3",         3, 7);
        check_reg("legal addi x5",         5, 9);
        check_reg("legal addi x7",         7, 1);
        check_reg("branch target x8",      8, 3);
        check_reg("wrong-path mulh x9",     9, 0);
        check_reg("bad custom-0 f7 NOP",  10, 0);
        check_reg("bad custom-0 f3 NOP",  11, 0);

        if (dut.dmem_inst.mem[0] !== 32'd0) begin
            $display("FAIL illegal sb wrote dmem[0] = 0x%08h", dut.dmem_inst.mem[0]); errors = errors + 1;
        end else $display("PASS illegal sb did not write dmem");

        if (illegal_flag !== 1'b1) begin
            $display("FAIL sticky illegal flag not set"); errors = errors + 1;
        end else $display("PASS sticky illegal flag set");

        if (illegal_pc !== 32'h4) begin
            $display("FAIL illegal_pc = 0x%08h, expected 0x00000004", illegal_pc); errors = errors + 1;
        end else $display("PASS illegal_pc = 0x%08h", illegal_pc);

        if (n_illegal !== 9) begin
            $display("FAIL committed illegal count = %0d, expected 9 (wrong-path one must not count)", n_illegal);
            errors = errors + 1;
        end else $display("PASS committed illegal count = %0d", n_illegal);

        if (errors == 0) $display("ALL ILLEGAL-INSTRUCTION TESTS PASSED");
        else             $display("ILLEGAL TEST FAILURES: %0d", errors);
        $finish;
    end

    initial begin
        #50000;
        $display("ERROR: tb_illegal timed out");
        $finish;
    end
endmodule
